// @whimtex-effect Samples/Survey Routes
// @control(_Opacity)
// @param hidden float _Opacity = 0.8 [0 .. 1]
// @param color _Tint = (1, 0.9019608, 0.7058824, 1)

float4 ApplyFX(float2 uv,float4 color){
 float path=.5+.17*sin(uv.x*8)+.055*sin(uv.x*23);
 float dash=step(.35,frac(uv.x*65));float route=exp(-abs(uv.y-path)*850)*dash;
 float marks=0;
 for(int i=0;i<4;i++){float x=.17+i*.21;float y=.5+.17*sin(x*8)+.055*sin(x*23);
 float2 p=uv-float2(x,y);float r=length(p);marks+=exp(-abs(r-.009)*1300)+exp(-r*900);
 marks+=(1-smoothstep(.0008,.002,abs(p.x)))*step(abs(p.y),.019)+(1-smoothstep(.0008,.002,abs(p.y)))*step(abs(p.x),.019);}
 return float4(_Tint.rgb,saturate(route+marks)*_Opacity);}

// @whimtex-effect Samples/Survey Grid
// @control(_Opacity)
// @param hidden float _Opacity = 0.25 [0 .. 1]
// @param float _Grid = 8 [2 .. 32]

float4 ApplyFX(float2 uv,float4 color){
 float2 p=abs(frac(uv*_Grid+.5)-.5);float grid=1-smoothstep(.006,.015,min(p.x,p.y));
 float cross=(1-smoothstep(.01,.02,p.x))*step(p.y,.07)+(1-smoothstep(.01,.02,p.y))*step(p.x,.07);
 float frame=1-smoothstep(.0015,.003,min(abs(uv.x-.035),min(abs(uv.x-.965),min(abs(uv.y-.035),abs(uv.y-.965)))));
 return float4(.68,.83,.73,saturate(grid*.35+cross+frame*.6)*_Opacity);}

// @whimtex-effect Samples/Brightness Contrast
// @control(_Opacity)
// @group
// @param hidden float _Opacity = 1 [0 .. 1] // Blend between the original colors and the adjusted result.
// @param float _Brightness = 2 [~-100 .. ~100] // Adjust midtone brightness while retaining black and white. Soft bounds allow stronger values.
// @param float _Contrast = 18 [~-100 .. ~100] // Positive increases tonal separation; negative brings tones toward middle gray. Soft bounds allow stronger values.
// @endgroup


// Rational tone curves avoid hard clipping and exponential overflow at extended settings.
// Work in the incoming RGB space, retaining signed/HDR values outside the tonal interval.
float AdjustTone(float value, float brightnessGain, float contrastGain)
{
    if (value <= 0.0 || value >= 1.0) return value;
    float low = value;
    float high = 1.0 - value;
    if (_Brightness >= 0.0) high /= brightnessGain;
    else low /= brightnessGain;
    // Carry the unnormalized pair into contrast: normalizing brightness first loses
    // the highlight distance to rounding, which extreme negative contrast amplifies.
    float nearEdge = 2.0 * min(low, high);
    float nearMiddle = abs(high - low);
    if (_Contrast >= 0.0) nearEdge /= contrastGain;
    else nearMiddle /= contrastGain;
    float mapped = 0.5 * (nearEdge / (nearEdge + nearMiddle));
    return low <= high ? mapped : 1.0 - mapped;
}

float4 ApplyFX(float2 uv, float4 color)
{
    if (_Brightness == 0.0 && _Contrast == 0.0) return color;
    float brightnessGain = 1.0 + abs(_Brightness) / 50.0;
    float contrastGain = 1.0 + abs(_Contrast) / 50.0;
	float4 result = color;
	result.rgb = float3(AdjustTone(color.r, brightnessGain, contrastGain),
        AdjustTone(color.g, brightnessGain, contrastGain),
        AdjustTone(color.b, brightnessGain, contrastGain));
	return lerp(color, result, _Opacity);
}

// @whimtex-effect Samples/Topographic Lines
// @control(_Opacity)
// @param hidden float _Opacity = 0.4 [0 .. 1]
// @group(Contours)
// @param float _Levels = 14 [2 .. 64]
// @param float _Width = 0.025 [0.01 .. 0.3]
// @param color _Ink = (1, 0.905882359, 0.7411765, 1)
// @endgroup

float4 ApplyFX(float2 uv,float4 color) {
 float value=color.r*_Levels;
 float dist=abs(frac(value+.5)-.5);
 float aa=max(fwidth(value),.002);
 float cover=1-smoothstep(_Width,_Width+aa,dist);
 return float4(_Ink.rgb,cover*_Opacity*_Ink.a);
}

